import { ref, reactive, onMounted } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import {
  apiAdminExpressList,
  apiAdminExpressSave,
  apiAdminExpressDel,
  type ExpressItem,
} from "@/api/shipping";

const list = ref<ExpressItem[]>([]);
const loading = ref(false);
const formVisible = ref(false);
const saving = ref(false);
const form = reactive({
  id: 0,
  name: "",
  code: "",
  sort: 0,
  is_show: 1,
});

async function load() {
  loading.value = true;
  try {
    list.value = await apiAdminExpressList();
  } catch (e) {
    ElMessage.error(e instanceof Error ? e.message : "加载失败");
  } finally {
    loading.value = false;
  }
}

function openForm(row?: ExpressItem) {
  if (row) {
    form.id = row.id;
    form.name = row.name;
    form.code = row.code || "";
    form.sort = row.sort;
    form.is_show = row.isShow;
  } else {
    form.id = 0;
    form.name = "";
    form.code = "";
    form.sort = 0;
    form.is_show = 1;
  }
  formVisible.value = true;
}

async function save() {
  if (!form.name) return ElMessage.error("请输入快递公司名称");
  saving.value = true;
  try {
    await apiAdminExpressSave({
      id: form.id || undefined,
      name: form.name,
      code: form.code,
      sort: form.sort,
      is_show: form.is_show,
    });
    ElMessage.success("保存成功");
    formVisible.value = false;
    load();
  } catch (e) {
    ElMessage.error(e instanceof Error ? e.message : "保存失败");
  } finally {
    saving.value = false;
  }
}

async function del(row: ExpressItem) {
  try {
    await ElMessageBox.confirm(`确认删除快递公司「${row.name}」?`, "删除确认", { type: "warning" });
  } catch {
    return;
  }
  try {
    await apiAdminExpressDel(row.id);
    ElMessage.success("已删除");
    load();
  } catch (e) {
    ElMessage.error(e instanceof Error ? e.message : "删除失败");
  }
}

onMounted(load);

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
