  } catch (error) {
    if (!active(stamp)) return;
    const message = error instanceof Error ? error.message : "删除用户分组失败";
    if (message.includes("该分组仍有用户")) ElMessage.warning("该分组仍有用户，不能删除。请先调整关联用户的分组。");
