  if (kind === 'hotspot') {
    const geometry = { left: 0, top: 0, width: 100, height: Math.min(100, 750 * Number(imageHeight) / Number(imageWidth)) };
    if (!validHotspotGeometry(geometry, Number(imageWidth), Number(imageHeight))) throw Error('请等待热区图片实际加载后再添加区域');
